script:
card({ name: "Feedback", icon: 'chat' });
const words = {
  how: "How did it go?",
  great: "Great",
  fine: "Fine",
  meh: "Not great",
  best: "The best bit",
  change: "One thing to change",
  send: "Send feedback",
  thanks: "Thanks! Your feedback went to the sender.",
  again: "Change my answers",
  none: "No feedback yet",
  count: "{p0} answered",
  host: "You sent this, so you see the answers",
};

// Everyone but the sender fills in the form; the sender sees the answers.
const moods = [words.great, words.fine, words.meh];

function init() {
  return { answers: {}, editing: {} };
}

on.answer = (s, args, ctx) => {
  if (ctx.author === ctx.sender) throw words.host;
  const v = args.values || {};
  s.answers[ctx.author] = { name: ctx.authorName, mood: v.mood ?? null, best: v.best || '', change: v.change || '' };
  delete s.editing[ctx.author];
};

on.edit = (s, args, ctx) => {
  s.editing[ctx.author] = true;
};

function view(s, me) {
  const all = Object.values(s.answers);
  if (me.isSender) {
    if (!all.length) return column([text(words.none, { bold: true }), text(words.host, { size: 'small', tone: 'muted' })]);
    const counts = moods.map((m, i) => all.filter(a => a.mood === i).length);
    return column([
      badge(words.count.replace('{p0}', all.length), { tone: 'accent' }),
      ...moods.map((m, i) => row([text(m), badge(String(counts[i]), { tone: counts[i] ? 'accent' : 'muted' })], { align: 'between' })),
      divider(),
      ...all.map(a => column([
        text(a.name, { bold: true }),
        a.best && text('👍 ' + a.best, { size: 'small' }),
        a.change && text('🔧 ' + a.change, { size: 'small' }),
      ])),
    ]);
  }
  if (s.answers[me.id] && !s.editing[me.id]) {
    return column([text(words.thanks, { tone: 'success' }), button(words.again, 'edit', null, { tone: 'muted' })]);
  }
  return form('feedback', [
    text(words.how, { bold: true }),
    choice('mood', moods),
    input('best', words.best),
    input('change', words.change),
  ], words.send, 'answer');
}
